import math
import numpy as np
from scipy.optimize import least_squares


def _predict_with(p, row):
    vmax, rho, c_loc = p
    u = float(row['u_now'])  # tau_scale = 1.0
    s = float(row['s_grad'])
    base = vmax * (1.0 - rho * s / (1.0 + s)) * (u / (1.2 + u))
    return base + c_loc * math.sqrt(max(u, 0.0))


def fit(train_rows):
    ys = np.array([float(r['y']) for r in train_rows], dtype=float)
    def residual(p):
        return np.array([_predict_with(p, r) for r in train_rows]) - ys
    result = least_squares(residual, x0=np.array([4.0, 0.5, 0.1]), bounds=([0.0, 0.0, -10.0], [100.0, 0.999, 10.0]))
    return result.x


def predict(row):
    return float(_predict_with(fit(train_rows), row))
